package dispatch

import "testing"

// TestSubjectAllowedForFanout_AllowsRegisteredBusinessSubjects pins the
// core allowlist behavior for #2409: a subject registered on
// eventbus.EventsStreamSubjects (or one of extraAllowedSubjectPrefixes)
// is eligible for browser fan-out.
func TestSubjectAllowedForFanout_AllowsRegisteredBusinessSubjects(t *testing.T) {
	cases := []string{
		"notifications.user.created.org_a", // notifications.>
		"workflow.execution.node.exec-1",   // workflow.execution.node.>
		"workflow.canvas.created",          // exact literal entry
		"range.feed.updated.user_42",       // range.feed.updated.>
		"range.job.progress.job-1",         // extraAllowedSubjectPrefixes
		"org.member.invited",               // org.>
	}
	for _, subject := range cases {
		if !subjectAllowedForFanout(subject) {
			t.Errorf("subjectAllowedForFanout(%q) = false, want true", subject)
		}
	}
}

// TestSubjectAllowedForFanout_DeniesUnregisteredSubjects is the
// deny-by-default half of the allowlist: a subject that was never added
// to eventbus.EventsStreamSubjects (or extraAllowedSubjectPrefixes) must
// never be eligible for fan-out, regardless of how plausible its shape
// looks. This is the structural fix for "any new sensitive subject leaks
// by default" — under the old denylist design this subject would have
// been forwarded.
func TestSubjectAllowedForFanout_DeniesUnregisteredSubjects(t *testing.T) {
	cases := []string{
		"some.brand.new.subject.nobody.reviewed",
		"internal.debug.dump",
		"", // empty subject must never match
	}
	for _, subject := range cases {
		if subjectAllowedForFanout(subject) {
			t.Errorf("subjectAllowedForFanout(%q) = true, want false", subject)
		}
	}
}

// TestSubjectAllowedForFanout_DeniesSensitivePrefixesEvenIfRegistered
// confirms deniedSubjectPrefixes wins even for subjects that ARE
// registered on eventbus.EventsStreamSubjects — audit.> and
// range.feed.exposure.> are both present there, and must still never be
// eligible for browser fan-out (Gate 5 / cascade-exposure trust boundary).
func TestSubjectAllowedForFanout_DeniesSensitivePrefixesEvenIfRegistered(t *testing.T) {
	cases := []string{
		"audit.range.post.created",
		"audit.workflow.execution_started",
		"range.feed.exposure.ex-1",
	}
	for _, subject := range cases {
		if subjectAllowedForFanout(subject) {
			t.Errorf("subjectAllowedForFanout(%q) = true, want false (denied prefix)", subject)
		}
	}
}


