// Package dispatch provides the SharedSubscriber type for consuming from a
// shared NATS JetStream consumer on behalf of a gateway instance and routing
// messages to in-process subscribers via the router package. This implements
// ADR-003 Pattern B, which replaces per-session durable consumers with a
// single shared consumer per gateway pod.
package dispatch

import (
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"log/slog"
	"strings"
	"sync"
	"time"

	"github.com/nats-io/nats.go/jetstream"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/eventbus"
	"github.com/zenithflowinc/omnicore-platform/services/ws-gateway/internal/router"
)

// Header names used for per-message routing. These are NATS message headers
// (not JWT claims); upstream publishers MUST set "x-tenant-id" for any event
// that should be deliverable to a WS session.
const (
	HeaderTenantID  = "x-tenant-id"
	HeaderUserID    = "x-user-id"
	HeaderRequestID = "x-request-id"
	// HeaderTenantAssertion carries the SignTenantAssertion-minted HMAC
	// assertion binding HeaderTenantID's value to "issued recently by a
	// holder of the shared key" (platform/libs/go/auth/tenant_assertion.go).
	// Run() rejects any message whose assertion is missing, expired, or
	// doesn't verify against x-tenant-id — a forged x-tenant-id header
	// alone is no longer sufficient to reach a browser session.
	HeaderTenantAssertion = "x-tenant-assertion"
)

// SharedConsumerDurable is the JetStream durable consumer name every
// ws-gateway pod binds to. Naming it (rather than leaving it ephemeral)
// is what turns per-pod ingest into a shared workqueue: JetStream
// load-balances pull deliveries across every process bound to the same
// durable name, so adding a pod grows shared throughput instead of
// multiplying total NATS egress (the ADR-003 gap this fixes — previously
// every pod ran its own ephemeral consumer, each pulling the full
// firehose independently).
const SharedConsumerDurable = "ws-gateway-fanout"

// deniedSubjectPrefixes lists subject prefixes that must NEVER reach a
// browser session even though they are registered on the canonical EVENTS
// stream subject list (eventbus.EventsStreamSubjects). allowedFanoutSubjects
// is derived as "everything on EventsStreamSubjects except these prefixes".
var deniedSubjectPrefixes = []string{
	// Audit twins carry HMAC-chained audit-log data for the audit log
	// only (Gate 5) — never for a browser.
	"audit.",
	// range.feed.exposure.<exercise_id> carries the cascade-internal
	// exposure envelope (event_id, exercise_id, post_ids, character_ids,
	// ...), which is instructor-facing only; forwarding it would leak
	// cascade internals to participant/X-clone browser sessions.
	"range.feed.exposure.",
}

// extraAllowedSubjectPrefixes lists subject prefixes that are legitimate
// real-time, browser-facing fan-out subjects but are deliberately absent
// from eventbus.EventsStreamSubjects because they bypass the transactional
// outbox entirely (EventsStreamSubjects documents outbox-published business
// subjects; it is not a complete registry of every subject ws-gateway must
// forward).
var extraAllowedSubjectPrefixes = []string{
	// range.job.progress.<job_id> — published directly by the range
	// audience worker (the documented ephemeral-progress exception to
	// outbox-only publishing), consumed by the instructor's WS session to
	// drive a progress bar. It lives on the dedicated RANGE_PROGRESS
	// stream's subtree, not EVENTS, precisely because it is high-frequency
	// and disposable — but ws-gateway still must forward it when it does
	// arrive on the shared NATS server.
	"range.job.progress.",
}

// allowedFanoutSubjects and allowedFanoutPrefixes together form the
// fan-out allowlist consulted by subjectAllowedForFanout. They are
// derived once, at package init, from eventbus.EventsStreamSubjects (the
// platform's canonical, change-controlled list of subjects captured by
// the EVENTS stream) plus extraAllowedSubjectPrefixes, with
// deniedSubjectPrefixes stripped out of both.
//
// This is a derived allowlist, not an independently hand-curated "known
// UI-consumed subjects" list: a subject reaches a browser if and only if
// it is registered on EventsStreamSubjects (already a reviewed,
// change-controlled process — an unregistered subject already
// head-of-line-blocks every Python outbox drainer, so there is strong
// existing pressure to keep it accurate) or explicitly listed in
// extraAllowedSubjectPrefixes, and is not under a denied prefix. This
// replaces the previous "denylist fan-out" design (forward everything
// except two known-sensitive prefixes) with allowlist fan-out (forward
// nothing except what is registered here): a subject that is never added
// to one of these two lists can never reach a browser, regardless of
// what an upstream service happens to publish on the shared NATS server.
// See the ws-gateway PR description (#2409) for the scope trade-off
// versus a fully independent hand-audited allowlist.
var (
	allowedFanoutSubjects = map[string]struct{}{}
	allowedFanoutPrefixes = []string{}
)

func init() {
	for _, subj := range eventbus.EventsStreamSubjects {
		if deniedByPrefix(subj) {
			continue
		}
		if strings.HasSuffix(subj, ".>") {
			allowedFanoutPrefixes = append(allowedFanoutPrefixes, strings.TrimSuffix(subj, ">"))
			continue
		}
		allowedFanoutSubjects[subj] = struct{}{}
	}
	for _, prefix := range extraAllowedSubjectPrefixes {
		if deniedByPrefix(prefix) {
			continue
		}
		allowedFanoutPrefixes = append(allowedFanoutPrefixes, prefix)
	}
}

// deniedByPrefix reports whether subj starts with one of deniedSubjectPrefixes.
func deniedByPrefix(subj string) bool {
	for _, denied := range deniedSubjectPrefixes {
		if strings.HasPrefix(subj, denied) {
			return true
		}
	}
	return false
}

// subjectAllowedForFanout reports whether subject is eligible for
// browser fan-out under the allowlist described above: either an exact
// literal match, or a match against one of the wildcard ("prefix.>")
// entries registered on EventsStreamSubjects.
func subjectAllowedForFanout(subject string) bool {
	if _, ok := allowedFanoutSubjects[subject]; ok {
		return true
	}
	for _, prefix := range allowedFanoutPrefixes {
		if strings.HasPrefix(subject, prefix) {
			return true
		}
	}
	return false
}

// tenantAssertionMaxAge bounds how old an x-tenant-assertion's issued_at
// may be before Run() rejects it. 5 minutes comfortably covers normal
// publish-to-consume latency (including outbox-drainer batching) while
// keeping the replay window tight.
const tenantAssertionMaxAge = 5 * time.Minute

// Router is the minimal contract SharedSubscriber depends on for in-process
// fan-out. The real *router.Router satisfies it; tests substitute a fake.
type Router interface {
	Dispatch(orgID string, frame router.Frame) (delivered, dropped int)
}

// SharedSubscriber consumes from a JetStream stream via a shared durable
// pull consumer (SharedConsumerDurable) and forwards each message to the
// in-process router. ADR-003 (Pattern B) replaces the per-session
// durable consumer with this design — consumer count drops from
// O(sessions) to O(pods), and every pod binding the same durable name
// shares NATS's native load-balancing across pull consumers, so ingest
// volume is shared rather than duplicated per pod (the fix for the
// full-firehose-per-pod gap).
//
// Cross-tenant isolation is enforced by the router; SharedSubscriber's
// structural filters are "drop messages missing x-tenant-id" (an
// orphaned message must not reach any session) and the fan-out allowlist
// (subjectAllowedForFanout) — a subject not registered on
// eventbus.EventsStreamSubjects (or extraAllowedSubjectPrefixes), minus
// deniedSubjectPrefixes, is dropped before it is ever handed to the
// router.
type SharedSubscriber struct {
	stream       string
	router       Router
	logger       *slog.Logger
	consumer     jetstream.Consumer
	assertionKey []byte
}

// NewSharedSubscriber creates (or rebinds to) the shared durable consumer
// on the named stream and returns a SharedSubscriber ready for Run.
// logger may be nil (falls back to slog.Default).
//
// Consumer config:
//   - Durable: SharedConsumerDurable — shared across every gateway pod so
//     JetStream load-balances pull deliveries across all of them (a NATS
//     "queue group" for pull consumers is simply every process binding
//     the same durable name).
//   - DeliverNewPolicy: starts at the live head. Replay across a full
//     process restart is out of scope — Router.Backlog covers the
//     narrower "client reconnects while at least one gateway pod has
//     been continuously up" case.
//   - AckExplicitPolicy: each delivered message is acked individually,
//     keeping the consumer's pending count bounded.
//   - FilterSubject ">": catch-all at the NATS layer, same as before —
//     the fan-out allowlist is enforced in-process (subjectAllowedForFanout)
//     rather than pushed into the consumer's FilterSubjects. NATS
//     validates that every FilterSubjects entry overlaps the stream's own
//     configured subjects; the allowlist derived from
//     eventbus.EventsStreamSubjects is wider than what most individual
//     streams (including test fixtures) actually declare, so pushing it
//     into FilterSubjects would make consumer creation fail depending on
//     the stream's subject set. The shared Durable name below is what
//     scopes ingest across pods; narrowing NATS-side delivery further is
//     deferred (see PR description).
//   - InactiveThreshold 5 minutes: guards against a permanently stuck
//     pod holding the durable's interest open with no live Run() loop.
//
// assertionKey is the shared HMAC key used to verify each message's
// x-tenant-assertion header against its x-tenant-id (see
// platform/libs/go/auth/tenant_assertion.go). It must be the exact same
// key value publishers sign with via auth.ForwardingContext /
// auth.TenantAssertionSigningKey — read from Vault at boot in
// cmd/server/main.go via vaultsecret.ReadTenantAssertionKey. An empty/nil
// key means every message fails verification (VerifyTenantAssertion
// requires a non-empty key), so a misconfigured gateway fails closed
// rather than silently accepting unsigned tenant headers.
func NewSharedSubscriber(
	ctx context.Context,
	js jetstream.JetStream,
	streamName string,
	r Router,
	logger *slog.Logger,
	assertionKey []byte,
) (*SharedSubscriber, error) {
	if logger == nil {
		logger = slog.Default()
	}
	cons, err := js.CreateOrUpdateConsumer(ctx, streamName, jetstream.ConsumerConfig{
		Name:              SharedConsumerDurable,
		Durable:           SharedConsumerDurable,
		AckPolicy:         jetstream.AckExplicitPolicy,
		DeliverPolicy:     jetstream.DeliverNewPolicy,
		FilterSubject:     ">",
		InactiveThreshold: 5 * time.Minute,
	})
	if err != nil {
		return nil, fmt.Errorf("ws-gateway: create shared consumer on %s: %w", streamName, err)
	}
	return &SharedSubscriber{
		stream:       streamName,
		router:       r,
		logger:       logger,
		consumer:     cons,
		assertionKey: assertionKey,
	}, nil
}

// drop logs why a message is being discarded (at Debug) and Acks it so
// JetStream stops redelivering. Shared by every structural filter in Run —
// the orphan drops (no headers / no x-tenant-id) and the allowlist-miss
// drops. The log message is "ws-gateway: dropped <reason>".
func (s *SharedSubscriber) drop(m jetstream.Msg, reason string) {
	s.logger.DebugContext(context.Background(), "ws-gateway: dropped "+reason,
		"subject", m.Subject())
	_ = m.Ack()
}

// Run starts pulling from the consumer and blocks until ctx is
// cancelled. Each delivered message is:
//
//  1. Header-checked for x-tenant-id; missing → drop (Ack).
//  2. Checked against the fan-out allowlist (subjectAllowedForFanout);
//     not allowed → drop (Ack).
//  3. x-tenant-assertion verified against x-tenant-id and assertionKey;
//     missing/expired/wrong-org/bad-signature → drop (Ack).
//  4. Built into a router.Frame (subject, base64 payload, request_id,
//     optional target user_id from x-user-id).
//  5. Forwarded via router.Dispatch.
//  6. Acked.
//
// Dispatch is non-blocking by contract — the shared subscriber must
// never be stalled by a slow-tab on any session.
//
// #2410 (P1-22) audit note: unlike notifications-svc's always-ACK bug this
// method's always-Ack is NOT a bug. Router.Dispatch is in-process, in-memory
// fan-out over live WS sessions — it returns (delivered, dropped int), never
// an error — so there is no failure for a Nak-backoff/dead-letter policy to
// react to. A dropped delivery here means "no session was listening right
// now", which is not a retryable condition (the message is stale by the time
// any redelivery would land) and not a data-loss bug the way an unhandled DB
// write failure would be. This consumer therefore intentionally keeps
// AckPolicy/always-Ack as-is; eventbus.Consumer's Nak-backoff+Term+DLQ
// semantics are not applicable to a fire-and-forget fan-out consumer. See
// issue #2409 for this file's fan-out/allowlist/resume mechanics, which are
// out of scope here.
//
// Run also arms a jetstream.ConsumeErrHandler so a terminal consumer
// failure (jetstream.ErrConsumerDeleted / ErrConsumerNotFound — e.g. the
// shared durable consumer being deleted out from under every pod during a
// long NATS outage) cancels Run's own derived context instead of leaving
// Run blocked on <-ctx.Done() forever. Without this, main.go's
// zombie-guard os.Exit(1) on a non-nil, non-context.Canceled Run error
// could never fire on a NATS-side failure: HTTP would stay healthy while
// fan-out was silently dead. Non-terminal errors (e.g. a missed
// heartbeat) are logged but do not cancel — the consumer can recover from
// those on its own.
func (s *SharedSubscriber) Run(ctx context.Context) error {
	runCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	var mu sync.Mutex
	var terminalErr error

	cc, err := s.consumer.Consume(func(m jetstream.Msg) {
		hdr := m.Headers()
		if hdr == nil {
			// No headers at all — orphan event, must not reach any session.
			s.drop(m, "message without headers")
			return
		}
		orgID := hdr.Get(HeaderTenantID)
		if orgID == "" {
			// Orphan event — must not reach any session. ACK so JetStream
			// doesn't redeliver indefinitely.
			s.drop(m, "message without x-tenant-id")
			return
		}
		if !subjectAllowedForFanout(m.Subject()) {
			// Deny-by-default: a subject not explicitly allowlisted (see
			// allowedFanoutSubjects/allowedFanoutPrefixes) must never
			// reach a browser session, regardless of tenant header.
			s.drop(m, "subject not in fan-out allowlist")
			return
		}
		// Verify the tenant assertion before trusting x-tenant-id. A
		// forged or replayed x-tenant-id must not reach any session —
		// missing/expired/wrong-org/bad-signature all fail closed the
		// same way as the "no x-tenant-id" drop above. Deliberately no
		// message body/PII in the log — subject + orgID only.
		assertion := hdr.Get(HeaderTenantAssertion)
		if assertion == "" || !auth.VerifyTenantAssertion(assertion, orgID, s.assertionKey, tenantAssertionMaxAge) {
			s.logger.WarnContext(context.Background(), "ws-gateway: dropped message with missing/invalid x-tenant-assertion",
				"subject", m.Subject(), "org_id", orgID)
			_ = m.Ack()
			return
		}
		frame := router.Frame{
			Subject:      m.Subject(),
			PayloadB64:   base64.StdEncoding.EncodeToString(m.Data()),
			RequestID:    hdr.Get(HeaderRequestID),
			TargetUserID: hdr.Get(HeaderUserID),
		}
		_, _ = s.router.Dispatch(orgID, frame)
		_ = m.Ack()
	}, jetstream.ConsumeErrHandler(func(_ jetstream.ConsumeContext, consumeErr error) {
		if !errors.Is(consumeErr, jetstream.ErrConsumerDeleted) && !errors.Is(consumeErr, jetstream.ErrConsumerNotFound) {
			s.logger.WarnContext(context.Background(), "ws-gateway: transient consume error", "err", consumeErr)
			return
		}
		s.logger.ErrorContext(context.Background(),
			"ws-gateway: shared consumer terminated; cancelling Run so the zombie guard can exit the process",
			"err", consumeErr)
		mu.Lock()
		terminalErr = consumeErr
		mu.Unlock()
		cancel()
	}))
	if err != nil {
		return fmt.Errorf("ws-gateway: shared consumer Consume: %w", err)
	}
	s.logger.InfoContext(ctx, "ws-gateway: shared subscriber started", "stream", s.stream)
	defer cc.Stop()
	<-runCtx.Done()

	mu.Lock()
	tErr := terminalErr
	mu.Unlock()
	if tErr != nil {
		return fmt.Errorf("ws-gateway: shared consumer terminated: %w", tErr)
	}
	return ctx.Err()
}


