package dispatch

import (
	"context"
	"log/slog"
	"testing"
	"time"

	"github.com/nats-io/nats.go/jetstream"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// fakeConsumeContext is a minimal jetstream.ConsumeContext double: Stop and
// Drain both just close the stopped channel, which is all Run's defer
// cc.Stop() call needs from it.
type fakeConsumeContext struct {
	stopped chan struct{}
}

func (f *fakeConsumeContext) Stop() {
	select {
	case <-f.stopped:
	default:
		close(f.stopped)
	}
}
func (f *fakeConsumeContext) Drain() { f.Stop() }
func (f *fakeConsumeContext) Closed() <-chan struct{} {
	return f.stopped
}

// fakeDyingConsumer is a jetstream.Consumer double whose Consume immediately
// (and asynchronously, like the real client) invokes the caller's
// jetstream.ConsumeErrHandler option — if one was supplied — with
// triggerErr. Every other Consumer method is unused by SharedSubscriber.Run
// and stubbed to zero values.
type fakeDyingConsumer struct {
	triggerErr error
}

func (f *fakeDyingConsumer) Consume(_ jetstream.MessageHandler, opts ...jetstream.PullConsumeOpt) (jetstream.ConsumeContext, error) {
	cc := &fakeConsumeContext{stopped: make(chan struct{})}
	for _, opt := range opts {
		if eh, ok := opt.(jetstream.ConsumeErrHandler); ok {
			go eh(cc, f.triggerErr)
		}
	}
	return cc, nil
}
func (f *fakeDyingConsumer) Fetch(int, ...jetstream.FetchOpt) (jetstream.MessageBatch, error) {
	return nil, nil
}
func (f *fakeDyingConsumer) FetchBytes(int, ...jetstream.FetchOpt) (jetstream.MessageBatch, error) {
	return nil, nil
}
func (f *fakeDyingConsumer) FetchNoWait(int) (jetstream.MessageBatch, error) { return nil, nil }
func (f *fakeDyingConsumer) Messages(...jetstream.PullMessagesOpt) (jetstream.MessagesContext, error) {
	return nil, nil
}
func (f *fakeDyingConsumer) Next(...jetstream.FetchOpt) (jetstream.Msg, error) { return nil, nil }
func (f *fakeDyingConsumer) Info(context.Context) (*jetstream.ConsumerInfo, error) {
	return nil, nil
}
func (f *fakeDyingConsumer) CachedInfo() *jetstream.ConsumerInfo { return nil }

// TestSharedSubscriber_Run_CancelsOnConsumerDeath pins the ws-gateway zombie
// guard: when the shared consumer terminates for real (jetstream.
// ErrConsumerDeleted — e.g. the ephemeral consumer's 5m InactiveThreshold
// reaping it during a long NATS outage that Part A's MaxReconnects(-1) no
// longer crashes the process for), Run must return promptly with a non-nil
// error that is NOT context.Canceled, so main.go's existing
// `if err != nil && !errors.Is(err, context.Canceled) { os.Exit(1) }` guard
// actually fires instead of silently blocking forever on <-ctx.Done().
func TestSharedSubscriber_Run_CancelsOnConsumerDeath(t *testing.T) {
	sub := &SharedSubscriber{
		stream:   "EVENTS",
		router:   &fakeRouter{},
		logger:   slog.Default(),
		consumer: &fakeDyingConsumer{triggerErr: jetstream.ErrConsumerDeleted},
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	errCh := make(chan error, 1)
	go func() { errCh <- sub.Run(ctx) }()

	select {
	case err := <-errCh:
		require.Error(t, err, "Run must return an error when the consumer dies")
		assert.NotErrorIs(t, err, context.Canceled,
			"a real consumer death must not look like a graceful shutdown")
		assert.ErrorIs(t, err, jetstream.ErrConsumerDeleted,
			"the returned error should wrap the terminal consumer error for diagnosability")
	case <-time.After(2 * time.Second):
		t.Fatal("Run did not return after the consumer terminated — the zombie guard's os.Exit(1) can never fire")
	}
}

// TestSharedSubscriber_Run_IgnoresTransientConsumeError confirms the flip
// side: a non-terminal consume error (e.g. a missed heartbeat) must NOT
// cancel Run — only genuine consumer termination should. Run should still
// be blocked on the parent context and only unblock (with context.Canceled)
// once the parent context itself is cancelled.
func TestSharedSubscriber_Run_IgnoresTransientConsumeError(t *testing.T) {
	sub := &SharedSubscriber{
		stream:   "EVENTS",
		router:   &fakeRouter{},
		logger:   slog.Default(),
		consumer: &fakeDyingConsumer{triggerErr: jetstream.ErrNoHeartbeat},
	}

	ctx, cancel := context.WithCancel(context.Background())
	errCh := make(chan error, 1)
	go func() { errCh <- sub.Run(ctx) }()

	select {
	case err := <-errCh:
		t.Fatalf("Run returned early on a transient error: %v", err)
	case <-time.After(300 * time.Millisecond):
		// Expected: Run is still blocked.
	}

	cancel()
	select {
	case err := <-errCh:
		assert.ErrorIs(t, err, context.Canceled)
	case <-time.After(2 * time.Second):
		t.Fatal("Run did not return after parent context cancellation")
	}
}


