// TestSharedSubscriber_DropsForgedTenantHeader confirms that a syntactically
// valid x-tenant-id is not, by itself, enough to reach a session: Run() must
// also verify x-tenant-assertion against it (platform/libs/go/auth/
// tenant_assertion.go). Three ways a message can fail that check, none of
// which should ever reach fakeRouter.Dispatch:
//
//  1. no x-tenant-assertion header at all,
//  2. an assertion validly signed but for a DIFFERENT org than x-tenant-id
//     claims (forged tenant header, valid signature),
//  3. an assertion for the right org whose issued_at is far in the past
//     (expired / replayed).
func TestSharedSubscriber_DropsForgedTenantHeader(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping NATS testcontainers test in -short mode")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	nc, js := startNATSContainer(t, ctx)
	defer nc.Close()

	const stream = "EVENTS"
	_, err := js.CreateOrUpdateStream(ctx, jetstream.StreamConfig{
		Name:     stream,
		Subjects: []string{"events.>"},
		Storage:  jetstream.FileStorage,
	})
	require.NoError(t, err)

	cases := []struct {
		name    string
		subject string
		build   func(t *testing.T) nats.Header
	}{
		{
			name:    "missing assertion header",
			subject: "events.forged.missing",
			build: func(t *testing.T) nats.Header {
				hdr := nats.Header{}
				hdr.Set(HeaderTenantID, "org_a")
				return hdr
			},
		},
		{
			name:    "assertion signed for a different org",
			subject: "events.forged.wrongorg",
			build: func(t *testing.T) nats.Header {
				assertion, err := auth.SignTenantAssertion("org_b", testAssertionKey)
				require.NoError(t, err)
				hdr := nats.Header{}
				hdr.Set(HeaderTenantID, "org_a")
				hdr.Set(HeaderTenantAssertion, assertion)
				return hdr
			},
		},
		{
			name:    "expired assertion",
			subject: "events.forged.expired",
			build: func(t *testing.T) nats.Header {
				assertion := signExpiredTenantAssertionForTest(t, "org_a", testAssertionKey)
				hdr := nats.Header{}
				hdr.Set(HeaderTenantID, "org_a")
				hdr.Set(HeaderTenantAssertion, assertion)
				return hdr
			},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			rec := &fakeRouter{notify: make(chan struct{}, 4)}
			sub, err := NewSharedSubscriber(ctx, js, stream, rec, nil, testAssertionKey)
			require.NoError(t, err)

			subCtx, subCancel := context.WithCancel(ctx)
			defer subCancel()
			go func() { _ = sub.Run(subCtx) }()

			hdr := tc.build(t)
			_, err = js.PublishMsg(ctx, &nats.Msg{
				Subject: tc.subject,
				Data:    []byte("payload"),
				Header:  hdr,
			})
			require.NoError(t, err)

			select {
			case <-rec.notify:
				t.Fatalf("router.Dispatch was called for %s — forged/expired tenant header must be dropped", tc.name)
			case <-time.After(2 * time.Second):
				// correct — no dispatch call
			}
			require.Empty(t, rec.snapshotCalls())
		})
	}
}

