// testAssertionKey is the shared HMAC key used by every test in this file
// to sign/verify x-tenant-assertion headers.
var testAssertionKey = []byte("shared-subscriber-test-tenant-assertion-key")

// fakeRouter records every Dispatch call so the test can assert on
// (orgID, frame) pairs the SharedSubscriber forwarded.
type fakeRouter struct {
	mu     sync.Mutex
	calls  []routerCall
	notify chan struct{}
}

type routerCall struct {
	OrgID string
	Frame router.Frame
}

// Dispatch satisfies the dispatch.Router interface used by SharedSubscriber.
func (f *fakeRouter) Dispatch(orgID string, fr router.Frame) (delivered, dropped int) {
	f.mu.Lock()
	f.calls = append(f.calls, routerCall{OrgID: orgID, Frame: fr})
	f.mu.Unlock()
	if f.notify != nil {
		select {
		case f.notify <- struct{}{}:
		default:
		}
	}
	return 1, 0
}

// snapshotCalls returns a defensive copy of the recorded calls under the
// mutex so test goroutines can read safely.
func (f *fakeRouter) snapshotCalls() []routerCall {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]routerCall, len(f.calls))
	copy(out, f.calls)
	return out
}

