// browser session in the org, including participant/X-clone sessions. That
// payload is instructor-facing only; it must never reach a browser (Phase B
// of epic #865, social-graph cascade info-leak fix).
func TestSharedSubscriber_DropsRangeFeedExposureSubjectMessage(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping NATS testcontainers test in -short mode")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	nc, js := startNATSContainer(t, ctx)
	defer nc.Close()

	const stream = "EVENTS"
	_, err := js.CreateOrUpdateStream(ctx, jetstream.StreamConfig{
		Name:     stream,
		Subjects: []string{"range.>"},
		Storage:  jetstream.FileStorage,
	})
	require.NoError(t, err)

	rec := &fakeRouter{notify: make(chan struct{}, 4)}
	sub, err := NewSharedSubscriber(ctx, js, stream, rec, nil, testAssertionKey)
	require.NoError(t, err)

	subCtx, subCancel := context.WithCancel(ctx)
	defer subCancel()
	go func() { _ = sub.Run(subCtx) }()

	// Publish with x-tenant-id set so the only reason it should be dropped
	// is the range.feed.exposure. subject filter (not the orphan-drop path).
	hdr := nats.Header{}
	hdr.Set(HeaderTenantID, "org_a")
	_, err = js.PublishMsg(ctx, &nats.Msg{
		Subject: "range.feed.exposure.ex-1",
		Data:    []byte(`{"event_id":"evt-1","exercise_id":"ex-1","post_ids":["p1"],"character_ids":["c1"]}`),
		Header:  hdr,
	})
	require.NoError(t, err)

	// Wait 2s: Dispatch must NOT have been called for a range.feed.exposure.* subject.
	select {
	case <-rec.notify:
		t.Fatal("router.Dispatch was called for a range.feed.exposure.* message — " +
			"cascade exposure envelopes are instructor-internal and must never reach browsers")
	case <-time.After(2 * time.Second):
		// correct — no dispatch call
	}
	require.Empty(t, rec.snapshotCalls(),
		"no Dispatch calls expected for range.feed.exposure.ex-1")
}

// TestSharedSubscriber_ForwardsRangeFeedUpdatedSubjectMessage is a regression
// guard: it confirms that the new range.feed.exposure. prefix drop does NOT
// over-match and swallow sibling range.feed.* subjects that ARE meant to
// reach browsers (e.g. range.feed.updated.<user_id>, published when a post
// or reaction lands in a participant's feed).
func TestSharedSubscriber_ForwardsRangeFeedUpdatedSubjectMessage(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping NATS testcontainers test in -short mode")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	nc, js := startNATSContainer(t, ctx)
	defer nc.Close()

	const stream = "EVENTS"
	_, err := js.CreateOrUpdateStream(ctx, jetstream.StreamConfig{
		Name:     stream,
		Subjects: []string{"range.>"},
		Storage:  jetstream.FileStorage,
	})
	require.NoError(t, err)

	rec := &fakeRouter{notify: make(chan struct{}, 4)}
	sub, err := NewSharedSubscriber(ctx, js, stream, rec, nil, testAssertionKey)
	require.NoError(t, err)

	subCtx, subCancel := context.WithCancel(ctx)
	defer subCancel()
	go func() { _ = sub.Run(subCtx) }()

	hdr := nats.Header{}
	hdr.Set(HeaderTenantID, "org_a")
	assertion, err := auth.SignTenantAssertion("org_a", testAssertionKey)
	require.NoError(t, err)
	hdr.Set(HeaderTenantAssertion, assertion)
	hdr.Set(HeaderUserID, "user_42")
	_, err = js.PublishMsg(ctx, &nats.Msg{
		Subject: "range.feed.updated.user_42",
		Data:    []byte(`{"post_id":"p1"}`),
		Header:  hdr,
	})
	require.NoError(t, err)

	select {
	case <-rec.notify:
	case <-time.After(3 * time.Second):
		t.Fatal("router never received a Dispatch call for range.feed.updated.* — " +
			"the range.feed.exposure. drop must not over-match sibling subjects")
	}

	calls := rec.snapshotCalls()
	require.Len(t, calls, 1)
	require.Equal(t, "org_a", calls[0].OrgID)
	require.Equal(t, "range.feed.updated.user_42", calls[0].Frame.Subject)
	require.Equal(t, "user_42", calls[0].Frame.TargetUserID)
}

// startNATSContainer boots a NATS testcontainer with JetStream and returns a
// connected client + js context. Named distinctly from the existing
// startNATS helper in dispatch_test.go (which has a different signature).
//
// JetStream is enabled by default by the tcnats module (it always passes
// "-js" to the server), so no extra arguments are needed.
//
// CI flake fix: tcnats.Run can return before the NATS server is ready to
// accept TCP — first nats.Connect occasionally got an immediate EOF on
// busy GitHub Actions runners. We retry the dial with a short backoff so
// the test doesn't fail on container-startup race.
func startNATSContainer(t *testing.T, ctx context.Context) (*nats.Conn, jetstream.JetStream) {
	t.Helper()
	c, err := tcnats.Run(ctx, "nats:2.10-alpine")
	require.NoError(t, err)
	t.Cleanup(func() { _ = c.Terminate(context.Background()) })

	host, err := c.ConnectionString(ctx)
	require.NoError(t, err)

	nc, err := connectNATSWithRetry(host, 30, 200*time.Millisecond)
	require.NoError(t, err)
	js, err := jetstream.New(nc)
	require.NoError(t, err)
	return nc, js
}

// connectNATSWithRetry dials the given NATS URL up to maxAttempts times,
// sleeping waitBetween between tries. Returns the first successful conn
// or the last error.
func connectNATSWithRetry(url string, maxAttempts int, waitBetween time.Duration) (*nats.Conn, error) {
	var lastErr error
	for i := 0; i < maxAttempts; i++ {
		nc, err := nats.Connect(url)
		if err == nil {
			return nc, nil
		}
		lastErr = err
		time.Sleep(waitBetween)
	}
	return nil, lastErr
}

// signExpiredTenantAssertionForTest builds a validly-signed tenant
// assertion whose issued_at is far enough in the past that
// auth.VerifyTenantAssertion's maxAge check must reject it, without
// depending on auth's unexported signing internals — it hand-computes the
// same HMAC-SHA256(payload) construction described in
// platform/libs/go/auth/tenant_assertion.go.
func signExpiredTenantAssertionForTest(t *testing.T, orgID string, key []byte) string {
	t.Helper()
	payload := orgID + "|" + strconv.FormatInt(time.Now().Add(-1*time.Hour).Unix(), 10) + "|aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
	mac := hmac.New(sha256.New, key)
	mac.Write([]byte(payload))
	sum := mac.Sum(nil)
	return base64.RawURLEncoding.EncodeToString([]byte(payload)) + "." +
		base64.RawURLEncoding.EncodeToString(sum)
}



